// terrain_rom.sv - the terrain map, 64 x 32 tiles, 4 bits per tile.
//
// Contents come from mem/map0.mem (generated by scripts/gen_map.py from
// maps/map0.txt). Address = {tile_y[4:0], tile_x[5:0]}.
//
// Port B: read by the renderer (drawcon) every clock.
// Port A (game logic: "is this tile passable?") will be added later as a
// second read port; the renderer side will not change.
//
// Read latency: 1 clock (data appears on the clock edge after addr is set).
`default_nettype none

module terrain_rom
  import game_pkg::*;
#(
  parameter string INIT_FILE = "map0.mem"
)(
  input  wire                  clk,
  input  wire [MAP_ADDR_W-1:0] addr_b,
  output logic [TERRAIN_W-1:0] data_b
);

  (* rom_style = "block" *)
  logic [TERRAIN_W-1:0] mem [MAP_W * MAP_H];

  initial $readmemh(INIT_FILE, mem);

  always_ff @(posedge clk) begin
    data_b <= mem[addr_b];
  end

endmodule

`default_nettype wire
